document.addEventListener("DOMContentLoaded",function(){const e=window.location.pathname.split("/").pop()||"index.html";document.querySelectorAll("nav a").forEach(t=>{t.getAttribute("href")===e&&t.classList.add("active")})}),document.addEventListener("DOMContentLoaded",()=>{document.querySelectorAll("img").forEach(e=>{e.hasAttribute("loading")||e.setAttribute("loading","lazy")}),function(){const e=document.querySelectorAll("main section, .feature-card, .stat-card, .gallery-item, .about-section, .service-item, .testimonial-card, .faq-item");if(!("IntersectionObserver"in window))return void e.forEach(e=>e.classList.add("is-visible"));const t=new IntersectionObserver((e,t)=>{e.forEach(e=>{e.isIntersecting&&(e.target.classList.add("is-visible"),t.unobserve(e.target))})},{threshold:.12});e.forEach(e=>{e.classList.add("reveal"),t.observe(e)})}()});